"""Debian package version comparison. See task.md."""

from __future__ import annotations


class VersionError(ValueError):
    """Raised for a string that is not a valid Debian version."""


_DIGITS = frozenset("0123456789")
_LETTERS = frozenset("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
_REV_CHARS = _DIGITS | _LETTERS | frozenset(".+~")
_UP_CHARS = _REV_CHARS | frozenset("-:")


def _parse(v: str) -> tuple[int, str, str]:
    if not isinstance(v, str) or not v:
        raise VersionError(f"invalid version: {v!r}")
    epoch = 0
    rest = v
    if ":" in v:
        e, rest = v.split(":", 1)
        if not e or not all(c in _DIGITS for c in e):
            raise VersionError(f"invalid epoch in {v!r}")
        epoch = int(e)
    rev = "0"
    up = rest
    if "-" in rest:
        up, rev = rest.rsplit("-", 1)
        if not rev:
            raise VersionError(f"empty revision in {v!r}")
    if not up or up[0] not in _DIGITS:
        raise VersionError(f"invalid upstream version in {v!r}")
    if not all(c in _UP_CHARS for c in up) or not all(c in _REV_CHARS for c in rev):
        raise VersionError(f"invalid character in {v!r}")
    return epoch, up, rev


def _weight(c: str | None) -> int:
    if c is None:
        return 0
    if c == "~":
        return -1
    if c in _LETTERS:
        return ord(c)
    return ord(c) + 256


def _split(s: str, i: int, digits: bool) -> int:
    n = len(s)
    while i < n and (s[i] in _DIGITS) == digits:
        i += 1
    return i


def _cmp_part(a: str, b: str) -> int:
    i = j = 0
    while i < len(a) or j < len(b):
        i2 = _split(a, i, False)
        j2 = _split(b, j, False)
        pa, pb = a[i:i2], b[j:j2]
        for k in range(max(len(pa), len(pb))):
            wa = _weight(pa[k] if k < len(pa) else None)
            wb = _weight(pb[k] if k < len(pb) else None)
            if wa != wb:
                return -1 if wa < wb else 1
        i3 = _split(a, i2, True)
        j3 = _split(b, j2, True)
        na = int(a[i2:i3] or "0")
        nb = int(b[j2:j3] or "0")
        if na != nb:
            return -1 if na < nb else 1
        i, j = i3, j3
    return 0


def compare(a: str, b: str) -> int:
    """Return -1, 0 or 1 as `a` sorts before, equal to, or after `b`."""
    ea, ua, ra = _parse(a)
    eb, ub, rb = _parse(b)
    if ea != eb:
        return -1 if ea < eb else 1
    return _cmp_part(ua, ub) or _cmp_part(ra, rb)


def sort_versions(versions: list[str]) -> list[str]:
    """Return `versions` in ascending order; equal versions keep their input order."""
    import functools

    items = list(versions)
    for v in items:
        _parse(v)
    return sorted(items, key=functools.cmp_to_key(compare))
